Modifying factor order
Often useful to change the order of the factor level in a visualization:

# Example: Exploring average number of hours spend watching TV per day across religions

relig_summary &lt;- gss_cat |&gt;
  group_by(relig) |&gt;
  summarize(
    tvhours = mean(tvhours, na.rm = TRUE),
    n = n()
  )

ggplot(
    data = relig_summary,
    mapping = aes(x = tvhours, y = relig)
  ) +
  geom_point()







# Hard reading this plot due to no overall pattern

# Can use fct_reorder()
# Three arguments:
# .f -&gt; factor (levels) to be modified; 
# .x -&gt; numeric vector used to reorder levels; 
# Optionally: .fun -&gt; function used if multiple values of .x for each value of .f; default is median

ggplot(
  data = relig_summary,
  mapping = aes(x = tvhours, y = fct_reorder(relig, tvhours))
) +
  geom_point()







# Recommendation: Move out of aes into mutate()
# relig_summary1 &lt;- relig_summary |&gt;
#  mutate(
#    relig = fct_reorder(relig, tvhours)
#  ) 

relig_summary |&gt;
  mutate(
    relig = fct_reorder(relig, tvhours)
  ) |&gt;
  ggplot(
    mapping = aes(x = tvhours, y = relig)
  ) +
  geom_point()







# Check first: factor(relig_summary$relig), note the order of levels
# Then check:  factor(relig_summary1$relig), notice reordering of levels in correspondance to values of tvhours


# Example fct_reorder()
# Average age varying across reported inc
rincome_summary &lt;- gss_cat |&gt;
  group_by(rincome) |&gt;
  summarize(
    avg_age = mean(age, na.rm = TRUE),
    n = n()
  )

ggplot(
  data = rincome_summary,
  mapping = aes(x = avg_age, y = rincome) 
) +
  geom_point()







ggplot(
  data = rincome_summary,
  mapping = aes(x = avg_age, y = fct_reorder(rincome, avg_age)) 
) +
  geom_point()







ggplot(
  data = rincome_summary,
  mapping = aes(x = avg_age, y = fct_relevel(rincome, "Not applicable") # can also be character string of levels
  )
) +
  geom_point()








fct_reorder() mostly makes sense for arbitrarily ordered levels of factors. However, can pull “Not applicable” to the other special levels to the front using fct_relevel(): Takes factor .f and any number of levels that we want to move to the front of the line (see `?fct_relevel```: … = function or character levels, default is after = 0…any levels not mentioned will be left in existing order).
Another type of ordering useful when coloring the lines on a plot. fct_reorder2(.f, .x, .y): reorders factor .f by .y values associated with largest .x values.

by_age &lt;- gss_cat |&gt;
  filter(!is.na(age)) |&gt; 
  count(age, marital) |&gt;
  group_by(age) |&gt;
  mutate(prop = n / sum(n))

by_age_plot &lt;- ggplot(
  data = by_age,
  mapping = aes(x = age, y = prop, color = marital)
) + 
  geom_line(linewidth = 1) +
  scale_color_brewer(palette = "Set1")

by_age_plot_fctreord &lt;- ggplot(
  data = by_age,
  mapping = aes(x = age, y = prop, color = fct_reorder2(marital, prop, age))
) + 
  geom_line(linewidth = 1) +
  scale_color_brewer(palette = "Set1")

by_age_plot + by_age_plot_fctreord








For bar plots can fct_infreq() to order levels in decreasing frequency (or use fct_rev() for reversed ordering):

gss_cat |&gt;
  mutate(marital = marital |&gt; fct_infreq() |&gt; fct_rev()) |&gt;
  ggplot(aes(x = marital)) + 
  geom_bar()
